Got it — you’re talking about a **linked list question** where you need to **separate even and odd elements** from a linked list, right?  

Here’s a clean, short C version of that problem:

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

// Create new node
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// Insert at end
struct Node* insertEnd(struct Node* head, int value) {
    struct Node* newNode = createNode(value);
    if (head == NULL)
        return newNode;

    struct Node* temp = head;
    while (temp->next != NULL)
        temp = temp->next;
    temp->next = newNode;
    return head;
}

// Display list
void display(struct Node* head) {
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

// Separate even and odd
void separateEvenOdd(struct Node* head) {
    struct Node *evenHead = NULL, *evenTail = NULL;
    struct Node *oddHead = NULL, *oddTail = NULL;

    while (head != NULL) {
        if (head->data % 2 == 0) {
            if (evenHead == NULL)
                evenHead = evenTail = createNode(head->data);
            else {
                evenTail->next = createNode(head->data);
                evenTail = evenTail->next;
            }
        } else {
            if (oddHead == NULL)
                oddHead = oddTail = createNode(head->data);
            else {
                oddTail->next = createNode(head->data);
                oddTail = oddTail->next;
            }
        }
        head = head->next;
    }

    printf("\nEven elements: ");
    display(evenHead);
    printf("Odd elements: ");
    display(oddHead);
}

int main() {
    struct Node* head = NULL;
    int n, val;

    printf("Enter number of nodes: ");
    scanf("%d", &n);

    printf("Enter elements:\n");
    for (int i = 0; i < n; i++) {
        scanf("%d", &val);
        head = insertEnd(head, val);
    }

    printf("\nOriginal list: ");
    display(head);

    separateEvenOdd(head);
    return 0;
}
```

### 🔍 What this does:
- Takes `n` numbers into a linked list.  
- Splits them into **even** and **odd** lists.  
- Prints both lists separately.

Do you want the even and odd lists to be **rejoined** (like even first then odd in one list)? I can tweak it for that version too.

Perfect — so you want a **clean version** where:  
- There are **separate functions**: one to extract evens, one for odds.  
- Each creates a **new linked list**.  
- Then you **merge** them together into a single final list (even first, then odd).  

Here’s the clean and fast version 👇

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

// --- Utility Functions ---
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

struct Node* insertEnd(struct Node* head, int value) {
    struct Node* newNode = createNode(value);
    if (head == NULL)
        return newNode;

    struct Node* temp = head;
    while (temp->next != NULL)
        temp = temp->next;
    temp->next = newNode;
    return head;
}

void display(struct Node* head) {
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

// --- Extract even list ---
struct Node* extractEven(struct Node* head) {
    struct Node* evenHead = NULL;
    while (head != NULL) {
        if (head->data % 2 == 0)
            evenHead = insertEnd(evenHead, head->data);
        head = head->next;
    }
    return evenHead;
}

// --- Extract odd list ---
struct Node* extractOdd(struct Node* head) {
    struct Node* oddHead = NULL;
    while (head != NULL) {
        if (head->data % 2 != 0)
            oddHead = insertEnd(oddHead, head->data);
        head = head->next;
    }
    return oddHead;
}

// --- Merge two lists ---
struct Node* mergeLists(struct Node* list1, struct Node* list2) {
    if (list1 == NULL) return list2;
    struct Node* temp = list1;
    while (temp->next != NULL)
        temp = temp->next;
    temp->next = list2;
    return list1;
}

// --- Main ---
int main() {
    struct Node* head = NULL;
    struct Node *evenList, *oddList, *mergedList;
    int n, val;

    printf("Enter number of nodes: ");
    scanf("%d", &n);

    printf("Enter elements:\n");
    for (int i = 0; i < n; i++) {
        scanf("%d", &val);
        head = insertEnd(head, val);
    }

    printf("\nOriginal list: ");
    display(head);

    evenList = extractEven(head);
    oddList = extractOdd(head);
    mergedList = mergeLists(evenList, oddList);

    printf("Even list: ");
    display(evenList);

    printf("Odd list: ");
    display(oddList);

    printf("Merged list (Even + Odd): ");
    display(mergedList);

    return 0;
}
```

### ✅ Highlights:
- `extractEven()` → builds a list with even elements.  
- `extractOdd()` → builds a list with odd elements.  
- `mergeLists()` → attaches the odd list after the even list.  
- **No redundant checks**, clean and fast traversal.  

